def monthly_total(orders, month):
    """Sum the paid orders of one month."""
    total = 0
    for order in orders:
        if order.month != month:
            continue
        if order.status == "paid":
            total += order.amount
    # refunds are booked as negative amounts
    return round(total, 2)

